package wb;
import android.app.*;import android.content.*;import android.os.*;
public class AssistantService extends Service {
 final Handler handler=new Handler(Looper.getMainLooper());PowerManager.WakeLock wake;Engine engine;long startedAt;boolean live;
 final BroadcastReceiver screens=new BroadcastReceiver(){public void onReceive(Context c,Intent i){engine.note("电源事件",String.valueOf(i.getAction())+" · WakeLock="+(wake!=null&&wake.isHeld()));if(Intent.ACTION_SCREEN_OFF.equals(i.getAction())&&engine.config().optBoolean("wakeLock",true)&&engine.config().optBoolean("enabled",true))wake.acquire(120000);}};
 final Runnable health=new Runnable(){public void run(){if(!live)return;org.json.JSONObject c=engine.config();boolean keep=c.optBoolean("wakeLock",true)&&c.optBoolean("enabled",true);if(keep){wake.acquire(120000);}else if(wake.isHeld())wake.release();engine.serviceHealth=true;engine.wakeHeld=wake.isHeld();engine.serviceUptime=SystemClock.elapsedRealtime()-startedAt;engine.reconnect();engine.note("保活心跳","WakeLock="+wake.isHeld()+" · interactive="+getSystemService(PowerManager.class).isInteractive()+" · "+engine.reader.status+" · "+engine.tts.status());handler.postDelayed(this,30000);}};
 public void onCreate(){super.onCreate();NotificationManager n=getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("doors","车门语伴",NotificationManager.IMPORTANCE_LOW));PendingIntent p=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE);startForeground(11,new Notification.Builder(this,"doors").setContentTitle("车门语伴正在聆听").setContentText("四门状态 · 本地播报 · AI 问候").setSmallIcon(android.R.drawable.ic_btn_speak_now).setContentIntent(p).build());engine=Engine.get(this);engine.start();startedAt=SystemClock.elapsedRealtime();wake=getSystemService(PowerManager.class).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"doorassistant:monitor");wake.setReferenceCounted(false);IntentFilter filter=new IntentFilter();filter.addAction(Intent.ACTION_SCREEN_ON);filter.addAction(Intent.ACTION_SCREEN_OFF);filter.addAction(Intent.ACTION_USER_PRESENT);filter.addAction(PowerManager.ACTION_DEVICE_IDLE_MODE_CHANGED);registerReceiver(screens,filter);live=true;handler.post(health);}
 public int onStartCommand(Intent i,int f,int id){return START_STICKY;}public IBinder onBind(Intent i){return null;}
 public void onDestroy(){live=false;try{unregisterReceiver(screens);}catch(Exception ignored){}handler.removeCallbacks(health);if(wake!=null&&wake.isHeld())wake.release();engine.serviceHealth=false;engine.wakeHeld=false;engine.close();super.onDestroy();}
}
